preConditionHook:
// PRICE HAS HELD BEYOND THE PRIOR SWING PIVOT FOR barsBeyond BARS WITHOUT A
// PULLBACK -- Brooks's stand-down rule. Once the "test" of the old extreme runs
// five or more bars past it without a single bar trading back to it, it is a
// successful breakout and not a reversal setup, and the countertrend trade is
// off. Stated positively here; the pane's negate toggle is how it is used as a
// blocker, which is why it is not written inverted.
//
// The count is of CONSECUTIVE bars back from this one whose low stayed above the
// level, so a single bar dipping to it ends the run -- that is the "without a
// pullback" clause. It is bounded by the pivot's own bars-ago index: the count
// cannot run past the bar that MADE the level.
//
// THE PIVOT SCAN IS INLINED from SwingHigh per the B-list decision -- rules in
// this corpus never reference each other -- and mirrors the twin's
// SwingHighBar / SwingHigh at Occurrence 1. MEASURED (EL_Swing_Probe.txt /
// el_swing_output1.txt, @ES 60 min):
//   * the pivot test is MIXED: the pivot bar is AT OR ABOVE the strength OLDER
//     bars and STRICTLY ABOVE the strength NEWER bars, so a flat top yields
//     exactly ONE pivot, the LATER of the equal bars. Bars-ago indexing makes
//     the SMALLER index the NEWER bar, so the strict half is the pk < pj loop;
//   * the confirmation lag is exactly strength bars, never 0 or 1, which is
//     what makes the scan lookahead-safe; during the lag the function returns
//     the PREVIOUS pivot, which scanning newest-first and taking the first hit
//     reproduces exactly;
//   * lookback is EL's Length: candidate offsets 0..lookback-1 from the current
//     bar INCLUSIVE, and the neighbourhood test reaches strength bars PAST the
//     window, so the deepest bar touched is lookback - 1 + strength;
//   * a window with no pivot returns the -1 SENTINEL, guarded explicitly here
//     because -1 as a PRICE sits under every real price and would make the long
//     side trivially true;
//   * the comparisons carry the 2.22e-12 relational tolerance, hence el_gt /
//     el_ge inside the scan rather than raw > and >=.
// The low side's TIE sense is the mirror of the measured high-side rule rather
// than an observation -- the probe's flat-extreme series was a flat TOP only.
// No WFSafe_SwingHigh exists, so plain EL governs.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
phBar = -1;
phVal = -1.0;
for (pj = (int)strength; pj <= (int)lookback - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_ge(high[pj], high[pk])) { pok = false; break; }
        }
    }
    if (pok) { phBar = pj; phVal = high[pj]; break; }
}
plBar = -1;
plVal = -1.0;
for (pj = (int)strength; pj <= (int)lookback - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_lt(low[pj], low[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_le(low[pj], low[pk])) { pok = false; break; }
        }
    }
    if (pok) { plBar = pj; plVal = low[pj]; break; }
}
cntUp = 0;
cntDn = 0;
doneUp = false;
doneDn = false;
for (ii = 0; ii <= (int)lookback - 1; ++ii) {
    if (doneUp == false && ii < phBar) {
        if (el_gt(low[ii], phVal)) {
            cntUp = cntUp + 1;
        } else {
            doneUp = true;
        }
    }
    if (doneDn == false && ii < plBar) {
        if (el_lt(high[ii], plVal)) {
            cntDn = cntDn + 1;
        } else {
            doneDn = true;
        }
    }
}
okUp = (phBar != -1) && el_ne(phVal, -1.0);
okDn = (plBar != -1) && el_ne(plVal, -1.0);
